def test_particle_communication_registration_order_is_semantically_invariant() -> (
    None
):
    """Produce the same primaries and semantic request rows after edge reordering."""
    wp = _warp()
    from particula.gpu.kernels.communication import (
        particle_communication_step_gpu,
    )

    def run(source: np.ndarray, destination: np.ndarray):
        particles, _ = _containers(
            np.ones(4), np.array([[4.0], [6.0], [0.0], [0.0]]), np.empty((4, 0))
        )
        particles.masses = wp.array(
            [[[2.0, 3.0]], [[5.0, 7.0]], [[0.0, 0.0]], [[0.0, 0.0]]],
            dtype=wp.float64,
            device="cpu",
        )
        particles.charge = wp.array(
            [[-2.0], [3.0], [0.0], [0.0]], dtype=wp.float64, device="cpu"
        )
        buffers = _particle_buffers(4, 1, 2)
        particle_communication_step_gpu(
            particles,
            _particle_configuration(source, destination, np.array([0.5, 0.5])),
            1.0,
            buffers,
        )
        wp.synchronize()
        semantic_rows = {
            (int(left), int(right)): (
                buffers.assignments.numpy()[index].copy(),
                buffers.request_concentrations.numpy()[index].copy(),
            )
            for index, (left, right) in enumerate(
                zip(source, destination, strict=True)
            )
        }
        return particles, semantic_rows

    first, first_rows = run(
        np.array([0, 1], dtype=np.int32), np.array([2, 3], dtype=np.int32)
    )
    second, second_rows = run(
        np.array([1, 0], dtype=np.int32), np.array([3, 2], dtype=np.int32)
    )

    for name in ("masses", "concentration", "charge", "density", "volume"):
        npt.assert_array_equal(
            getattr(first, name).numpy(), getattr(second, name).numpy()
        )
    assert first_rows.keys() == second_rows.keys()
    for key in first_rows:
        for actual, expected in zip(
            first_rows[key], second_rows[key], strict=True
        ):
            npt.assert_array_equal(actual, expected)

def test_native_transport_rejects_invalid_state_without_primary_writes(
    device, failure
):
    """A bad plan cannot modify source or destination primary state."""
    from particula.gpu.kernels import communication as module

    particles, _ = population(device)
    config = configuration(device)
    if failure == "overdraw":
        config.communication_map.rates.assign(np.array([2.0]))
    elif failure == "density":
        particles.volume.assign(np.array([0.25, 1e-310]))
    elif failure == "mass":
        values = particles.masses.numpy()
        values[0, 0, 0] = np.nan
        particles.masses.assign(values)
    else:
        particles.charge = particles.concentration
    buffers = module.ParticleCommunicationBuffers(
        wp.empty((2, 2), dtype=wp.float64, device=device),
        wp.empty((2, 2), dtype=wp.float64, device=device),
        wp.empty((1, 2), dtype=wp.int32, device=device),
        wp.empty((1, 2), dtype=wp.float64, device=device),
    )
    fields = (
        particles.masses,
        particles.concentration,
        particles.charge,
        particles.volume,
    )
    before = [array.numpy().copy() for array in fields]
    if failure == "alias":
        with pytest.raises(ValueError, match="alias"):
            module.particle_communication_step_gpu(
                particles, config, 1.0, buffers
            )
    else:
        module.particle_communication_step_gpu(particles, config, 1.0, buffers)
    wp.synchronize()
    for array, expected in zip(fields, before, strict=True):
        np.testing.assert_array_equal(array.numpy(), expected)

